INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-490c-729e-8864-db06688fb739', '01a20f16-41f0-70a0-8d4b-1bfcdd83ca81', '01a20f16-41e6-72fe-becd-116607ff288f', 'Dimensionner une mini-centrale solaire pour un village de 400 foyers', 'demo-dimensionner-une-mini-centrale-solaire-pour-un-village-de-40', 'Un village de 400 foyers n''est pas raccordé au réseau. Nous envisageons une mini-centrale solaire avec stockage, financée en partie par des paiements mensuels des ménages. Nous avons des relevés de consommation approximatifs et un ensoleillement moyen, mais pas d''étude de dimensionnement ni de modèle économique solide.', 'Estimer la demande d''énergie par type d''usage (ménages, commerces, pompe à eau).
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-491e-725f-bf5e-957c4cf54bf4', '01a20f16-41f0-70a0-8d4b-1bfcdd83ca81', '01a20f16-41e6-72fe-becd-116607ff288f', 'Tableau de bord de suivi à distance de la production d''installations solaires', 'demo-tableau-de-bord-de-suivi-a-distance-de-la-production-d-insta', 'Nos installations remontent leur production par des boîtiers simples, mais les données arrivent dans des fichiers dispersés. Les techniciens découvrent les pannes quand le client appelle. Nous voulons voir en un coup d''œil l''état de chaque site, être alertés des anomalies et planifier les tournées de maintenance.', 'Centraliser les données de production dans une base unique.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-492b-73a8-a940-633e78ecff09', '01a20f16-435a-77b8-b029-d195492e1fdb', '01a20f16-4352-70ef-a38e-d9aefe7a2ca8', 'Réduire les rendez-vous manqués grâce à des rappels par SMS', 'demo-reduire-les-rendez-vous-manques-grace-a-des-rappels-par-sms', 'Environ un rendez-vous sur quatre n''est pas honoré dans notre clinique, ce qui désorganise les consultations et retarde les soins. Les rendez-vous sont notés dans un tableur. Nous souhaitons comprendre les causes des absences et tester un système de rappel adapté à nos patients, dont beaucoup n''ont qu''un téléphone basique.', 'Analyser un an d''historique de rendez-vous pour identifier les profils et créneaux à risque.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4938-7629-a643-04bcb097aac1', '01a20f16-435a-77b8-b029-d195492e1fdb', '01a20f16-4352-70ef-a38e-d9aefe7a2ca8', 'Cartographier le parcours patient aux urgences et réduire l''attente', 'demo-cartographier-le-parcours-patient-aux-urgences-et-reduire-l-', 'Aux heures de pointe, l''attente aux urgences dépasse deux heures et génère des plaintes. Nous ne savons pas précisément où le temps est perdu : accueil, tri, examens, résultats ou sortie. Nous voulons une vision chiffrée du parcours et des actions simples à tester.', 'Cartographier le parcours du patient de l''arrivée à la sortie.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4948-745a-bf75-90e5af1d5abc', '01a20f16-44bc-770e-984d-72dce9d4505c', '01a20f16-44b6-7483-b6ff-354f1d459efd', 'Plateforme de soutien scolaire utilisable hors ligne pour le collège', 'demo-plateforme-de-soutien-scolaire-utilisable-hors-ligne-pour-le', 'Nos élèves de collège ont souvent un smartphone d''entrée de gamme et une connexion qui coupe. Nous voulons une application de révisions (mathématiques et sciences) qui télécharge des exercices lorsque le réseau est disponible, puis fonctionne sans connexion et synchronise les résultats ensuite.', 'Concevoir l''expérience élève : exercices courts, progression, retours immédiats.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4956-7448-a126-44ee953753e3', '01a20f16-44bc-770e-984d-72dce9d4505c', '01a20f16-44b6-7483-b6ff-354f1d459efd', 'Mesurer l''impact des formations d''enseignants sur les résultats des élèves', 'demo-mesurer-l-impact-des-formations-d-enseignants-sur-les-result', 'Nous formons chaque année des centaines d''enseignants, mais nous n''avons aucune mesure de l''effet sur leurs pratiques et sur les résultats des élèves. Nous souhaitons un protocole d''évaluation simple et crédible, testé sur une promotion récente.', 'Définir des indicateurs d''impact réalistes (pratiques en classe, résultats, satisfaction).
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4962-751c-a4b8-8644c1a37eb4', '01a20f16-4624-768c-8934-beeef2f20b50', '01a20f16-461f-7122-8550-77a08230c1c0', 'Digitaliser le réassort des boutiques de quartier', 'demo-digitaliser-le-reassort-des-boutiques-de-quartier', 'Nous livrons environ 600 boutiques de quartier. Les commandes arrivent par appel et messages vocaux, ce qui provoque des erreurs et des ruptures. Les gérants utilisent surtout WhatsApp. Nous cherchons un moyen simple de passer commande, de suivre les livraisons et de proposer un réassort basé sur les ventes habituelles.', 'Comprendre les habitudes de commande de dix gérants de boutique.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-496e-76dd-bc94-77779ad4ea88', '01a20f16-4624-768c-8934-beeef2f20b50', '01a20f16-461f-7122-8550-77a08230c1c0', 'Prévoir la demande et optimiser les stocks d''un entrepôt', 'demo-prevoir-la-demande-et-optimiser-les-stocks-d-un-entrepot', 'Notre entrepôt connaît à la fois des ruptures sur les produits les plus vendus et des surstocks sur d''autres, notamment avant les fêtes et le Ramadan. Nous disposons de deux ans d''historique de ventes par produit. Nous voulons une méthode de prévision simple et des seuils de réapprovisionnement par famille de produits.', 'Nettoyer et analyser l''historique de ventes.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-497c-72c6-9822-d4915f40da8c', '01a20f16-478f-7257-b931-208586f8cc56', '01a20f16-4789-7630-8764-c45d41b74aba', 'Audioguide multilingue pour la découverte d''un site patrimonial', 'demo-audioguide-multilingue-pour-la-decouverte-d-un-site-patrimon', 'Nous accueillons des groupes sur un site patrimonial sans signalétique ni audioguide. Les guides sont peu nombreux et les visiteurs étrangers repartent avec peu d''informations. Nous voulons un parcours de visite sur smartphone, en français, anglais et wolof, qui fonctionne sans connexion une fois téléchargé.', 'Définir le parcours de visite et rédiger les contenus avec les guides locaux.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4989-76ce-bcc9-9062baee2b1e', '01a20f16-48fd-75ce-a20e-a4cf574247b2', '01a20f16-48f7-75be-8ae9-d14320fa5e55', 'Cartographier et suivre l''entretien des points d''eau villageois', 'demo-cartographier-et-suivre-l-entretien-des-points-d-eau-village', 'Nous avons installé plus de 300 forages et puits dans la région, mais nous ne savons pas lesquels fonctionnent encore. Les pannes sont signalées par téléphone et traitées au cas par cas. Nous voulons un inventaire géolocalisé, un moyen simple de signaler une panne et un suivi des interventions.', 'Constituer un inventaire géolocalisé à partir des listes existantes et d''une collecte terrain.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-4995-7258-ab46-0952fd44267b', '01a20ef6-e5cd-71bc-835c-eb522810311e', '01a20ef6-e5c2-762b-9afc-1241b5527f81', 'Valoriser les déchets de transformation de la mangue et de l''arachide', 'demo-valoriser-les-dechets-de-transformation-de-la-mangue-et-de-l', 'Notre unité de transformation produit chaque semaine des tonnes de noyaux de mangue, de peaux et de coques d''arachide, aujourd''hui jetés ou brûlés. Nous voulons savoir s''il existe des débouchés viables : alimentation animale, combustible, compost, cosmétique.', 'Quantifier les volumes et la qualité des déchets par produit.
INSERT INTO public."Challenge" (id, "companyId", "createdById", title, slug, context, objectives, "sectorId", keywords, "teamSize", "minStudyLevel", "desiredStart", "durationWeeks", "budgetAmount", "budgetCurrency", "budgetPublic", "paymentTerms", status, "rejectionReason", "publishedAt", "closedAt", "closeReason", "isDemo", "createdAt", "updatedAt") VALUES ('01a20f16-49a2-75bb-8385-570499f7e601', '01a20ef6-e72c-7772-8b9d-66199eec8994', '01a20ef6-e726-70c5-89ae-096135f5c4cc', 'Détecter les transactions de paiement mobile suspectes : analyse exploratoire', 'demo-detecter-les-transactions-de-paiement-mobile-suspectes-analy', 'Nous observons des schémas de fraude sur notre service de paiement mobile : multiplication de petits transferts, comptes ouverts puis vidés en quelques heures. Nous mettons à disposition un jeu de données anonymisé et simulé pour explorer des méthodes de détection avant tout projet industriel.', 'Explorer le jeu de données et caractériser les comportements normaux et suspects.
